/* @autogenerated */
import {
  OBSERVED_ALERT_EXCEL_SENSITIVE,
  OBSERVED_ALERT_EXCEL_COLUMNS,
} from 'app/features/observe/observed-alert/model/observed-alert-excel-columns';
import { BaseExportAction } from 'app/shared/toolkit/action/base-export-action';
import { ExportDefinition } from 'app/shared/toolkit/entity-export/entity-export.model';
import { take, map } from 'rxjs';
import { ObservedAlertRepository } from 'app/features/observe/observed-alert/repository/observed-alert-repository.service';
import { ObservedAlertRuleRepository } from 'app/features/observe/observed-alert-rule/repository/observed-alert-rule-repository.service';
import { ObservedAlert } from 'app/features/observe/observed-alert/model/observed-alert.model';
import { Component, inject } from '@angular/core';

@Component({
  selector: 'observed-alert-view-export-action',
  standalone: false,
  templateUrl: './observed-alert-view-export-action.component.html',
})
export class ObservedAlertViewExportActionComponent extends BaseExportAction<ObservedAlert> {
  protected readonly scope = 'observe/observed-alert';
  protected readonly repository = inject(ObservedAlertRepository);
  private readonly ruleRepository = inject(ObservedAlertRuleRepository);

  readonly definition: ExportDefinition<ObservedAlert> = {
    name: 'observe.observed-alert',
    scope: this.scope,
    // Las mismas columnas que la importación: el fichero se puede editar y volver a subir
    columns: OBSERVED_ALERT_EXCEL_COLUMNS,
    sensitive: OBSERVED_ALERT_EXCEL_SENSITIVE,
    references: {
      rule: {
        names: (refs) =>
          this.ruleRepository.values({ uids: refs, limit: refs.length }).pipe(
            take(1),
            map((found) => Object.fromEntries(found.map((one) => [one.uid, String(one.name ?? '')]))),
          ),
      },
    },
    source: {
      acl: () => this.repository.checkAcl(),
      list: (filter) => this.repository.list(filter).pipe(take(1)),
    },
  };
}
